from sk import *
GL=['dragon_head','wolf_head','eagle_emblem','ghost','flame','sun','moon','snowflake_1','rose','crown','castle','tower_flag','compass','world','treasure_map','key']
CL=['#a05010','#5a3a90','#2a4a7a','#1f6a5a','#8a2a30','#6a6a20','#3a5a8a','#5a2a6a']
def lrow(i,g,name,sub,right='',hl=False,dim=False,fav=False,sz=34):
    return f'<div class="row{" hl" if hl else (" alt" if i%2 else "")}" style="height:{sz+10}px">{ic(g,CL[i%8],sz,dim=dim)}<div style="flex:1;min-width:0"><div style="font-weight:600;{"color:#7d808b" if dim else ""}">{name}{" <span class=gold>★</span>" if fav else ""}</div><div class="mut" style="font-size:10.5px">{sub}</div></div>{right}</div>'
def filt(ph,ch,on=(0,)): return f'<div style="display:flex;gap:8px;align-items:center;padding:10px 12px"><div class="srch" style="width:260px">⌕ {ph}</div>{chips(ch,on)}<span class="dd" style="width:140px;margin-left:auto">Sort: Name</span></div>'
T=['Mounts','Pet Journal','Toy Box','Heirlooms','Appearances','Campsites','Warband scenes']
# 04 mounts + pets
ms=[('Emberwing Phoenix','Flying · Skyriding','',True),('Ashen Courser','Ground','',False),('Cinder Drake','Flying · Skyriding','',True),('Obsidian Wolf','Ground','',False),('Dawnfire Hawk','Flying','',False),('Spectral Stag','Ground · not collected','',False),('Storm Gryphon','Flying','',False),('Molten Basilisk','Ground · not collected','',False)]
L=''.join(lrow(i,GL[i],n,s,'',hl=i==0,dim='not' in s,fav=f) for i,(n,s,_,f) in enumerate(ms))
body=filt('Search 1,042 mounts',['Collected','Not collected','Skyriding','Favourites'])+at(12,52,L,440)+model(466,56,644,330,'Mount ModelScene · Blizzard renders, Phoenix backdrop')
body+=at(466,396,f'<div class="card" style="padding:10px 12px;width:644px"><div class="ph">Emberwing Phoenix <span class="gold">★</span></div><div class="mut" style="margin:3px 0 8px">Drop · Ashen Spire, mythic · 1 of 1,042 collected mounts</div>{btn("Mount","p")} {btn("Summon random favourite")} {btn("Link")}</div>')
w=win(28,72,1136,520,'Collections',body,icon='Icons__Modules__64__vault',sub='Warband collections · 1,042 / 1,358 mounts',tabs=T,active=0)
pets=''.join(f'<div class="card" style="padding:8px;display:flex;gap:8px;align-items:center;width:250px">{ic(GL[i+4],CL[i],38)}<div style="flex:1"><div style="font-weight:600">{n}</div><div class="mut" style="font-size:10px">Level 25 · {q}</div>{bar(hp,"#3DDC97",6)}</div></div>' for i,(n,q,hp) in enumerate([('Ember Whelp','<span style=color:#0070dd>Rare</span>',100),('Ashling','<span style=color:#0070dd>Rare</span>',64),('Cinder Moth','<span style=color:#1eff00>Uncommon</span>',88)]))
w2=win(28,608,1136,170,'Pet Journal',f'<div style="display:flex;gap:10px;padding:12px;align-items:center"><span class="lbl" style="width:90px">Battle team</span>{pets}<span style="margin-left:auto">{btn("Revive","p")} {btn("Bandage")}</span></div>',icon='Icons__Modules__64__vault',sub='tab preview · 3 slot team + heal bar',z=11)
s=side('partial','Skins pack <b>collections</b> (CollectionsJournal): shell, tabs and close only. Mount/pet lists, model scenes, filter dropdowns, progress bars and journal-specific frames keep Blizzard art.',
 ['List rows: Phoenix tile icon, name, source line, ★ favourite, not-collected dimmed','One search + filter chips per tab (mounts, pets, toys, heirlooms, appearances)','Model scenes keep Blizzard 3D; Phoenix backdrop and frame','Pet team cards with health bar; revive/bandage as Phoenix buttons'],
 ['Summon/mount buttons call protected-safe C_MountJournal / C_PetJournal only from Blizzard\'s own buttons: <b>Phoenix only restyles them</b>','ScrollBox rows: hooksecurefunc on the ScrollBox element initializer, texture + font only','Model scenes cannot be restyled inside; only their backdrop (alpha on Blizzard bg, Phoenix texture behind)'],
 ['Skin on/off','Row height','Dim uncollected','Source line','Model backdrop','Accent'])
page('04_collections_mounts_pets','Collections · mounts & pets','Skins · Ember theme · CollectionsJournal',w+w2+s)

# 05 toys, heirlooms, appearances
def tile(i,n,dim=False,q='rare'): return f'<div style="text-align:center;width:96px">{ic(GL[i%16],CL[i%8],52,q=q,dim=dim)}<div style="font-size:10.5px;margin-top:4px;{"color:#7d808b" if dim else ""};white-space:nowrap;overflow:hidden">{n}</div></div>'
toys=['Ember Lantern','Phoenix Feather','Ashen Mirror','Cinder Drum','Kindling Kit','Glowing Orb','Spark Box','Dawn Bell','Ash Totem','Flame Puppet','Coal Dice','Smoke Bomb']
tb='<div style="display:flex;flex-wrap:wrap;gap:12px 8px;padding:6px 14px">'+''.join(tile(i,n,dim=i in(4,9),q='rare' if i%3 else 'epic') for i,n in enumerate(toys))+'</div>'
w=win(28,72,560,420,'Toy Box',filt('Search toys',['Usable','Not collected'])+tb+'<div class="abs mut" style="left:14px;bottom:12px">812 / 1,004 toys · page 1 / 9</div>',icon='Icons__Modules__64__vault',sub='tab preview',tabs=['Mounts','Pet Journal','Toy Box','Heirlooms','Appearances'],active=2)
hl=''.join(f'<div style="text-align:center;width:96px">{ic(GL[i+3],CL[i],52,q="heir")}<div style="font-size:10.5px;margin-top:4px;color:#00ccff">{n}</div><div style="display:flex;gap:2px;justify-content:center;margin-top:3px">'+''.join(f'<span style="width:12px;height:4px;border-radius:2px;background:{"#00ccff" if k<r else "#2a2c33"}"></span>' for k in range(4))+'</div></div>' for i,(n,r) in enumerate([('Burnished Blade',4),('Ancestral Staff',3),('Sooty Shoulders',4),('Ember Charm',2),('Ring of Ash',1),('Cindered Cloak',4),('Polished Helm',3),('Ashen Legs',0)]))
w2=win(604,72,560,420,'Heirlooms','<div style="padding:10px 14px;display:flex;gap:6px">'+chips(['All classes','Monk','Weapons','Armor','Trinkets'],(1,))+'</div><div style="display:flex;flex-wrap:wrap;gap:16px 10px;padding:6px 14px">'+hl+'</div><div class="abs mut" style="left:14px;bottom:12px">Upgrade level pips · 124 / 162 heirlooms</div>',icon='Icons__Modules__64__vault',sub='tab preview',z=11)
ap='<div style="display:flex;gap:12px;padding:12px"><div style="width:180px">'+''.join(f'<div class="row{" hl" if i==4 else ""}" style="height:30px">{ic(GL[i],CL[i%8],20)}<span>{s}</span></div>' for i,s in enumerate(['Head','Shoulder','Back','Chest','Hands','Waist','Legs','Feet','Weapons']))+'</div><div style="display:grid;grid-template-columns:repeat(6,1fr);gap:10px;flex:1">'+''.join(f'<div class="card" style="height:112px;position:relative;{"border-color:var(--acc)" if i==2 else ""}"><div class="model" style="inset:6px;border:0"><div class="fig" style="width:52%"></div></div>{"<span class=chip style=position:absolute;right:4px;top:4px>✓</span>" if i%4!=3 else "<span class=chip style=position:absolute;right:4px;top:4px;color:#ff5468>✕</span>"}</div>' for i in range(12))+'</div></div>'
w3=win(28,508,1136,330,'Appearances',ap,icon='Icons__Modules__64__vault',sub='Items · Sets · per-slot grid, collected ✓ / missing ✕',tabs=['Items','Sets'],z=12)
s=side('partial','Same CollectionsJournal pack; toy/heirloom tiles, the appearance grid and set browser are not touched today.',
 ['Toy/heirloom tiles: Phoenix tile + quality border, uncollected greyed','Heirloom upgrade pips in heirloom colour','Appearance grid: Phoenix cards, collected ✓ / missing ✕ chips, accent on hover/selected','Slot rail in Phoenix rows'],
 ['Toys are <b>secure action buttons</b> (use toy): never SetAttribute or move; restyle the icon border and font only','Appearance cards are DressUpModel frames: restyle their border/bg textures, never the model','Wardrobe frames are shared with Transmog: one skin function covers both (no double hooks)'],
 ['Skin on/off','Tile size','Grey uncollected','Upgrade pips','Card hover glow'])
page('05_collections_toys_heirlooms_appearances','Collections · toys, heirlooms, appearances','Skins · Ember theme · CollectionsJournal tabs',w+w2+w3+s)

# 06 transmog
sl=''.join(f'<div class="row{" hl" if i==3 else ""}" style="height:44px">{ic(g,CL[i%8],32,q="epic")}<div style="flex:1"><div style="font-weight:600;font-size:11px">{n}</div><div class="mut" style="font-size:10px">{"Pending change" if i==3 else "Current look"}</div></div></div>' for i,(g,n) in enumerate([('visored_helm','Head'),('shield','Shoulder'),('hood','Back'),('heart_shield','Chest'),('fist','Hands'),('stars_stack','Waist'),('run','Legs'),('sprint','Feet')]))
grid='<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:8px">'+''.join(f'<div class="card" style="height:118px;position:relative;{"border-color:var(--acc);box-shadow:0 0 14px rgba(255,122,26,.3)" if i==6 else ""}"><div class="model" style="inset:5px;border:0"><div class="fig" style="width:50%"></div></div></div>' for i in range(10))+'</div>'
b=at(12,10,sl,210)+model(234,14,330,400,'Your character · Blizzard model')+at(578,10,'<div style="width:540px"><div style="display:flex;gap:6px;margin-bottom:8px"><div class="srch" style="width:220px">⌕ Search chest appearances</div>'+chips(['Collected','Usable','Armor type'],(0,1))+'</div>'+grid+'</div>')
b+=at(12,432,'<div class="card" style="width:1108px;padding:10px 12px;display:flex;gap:10px;align-items:center"><span class="lbl">Outfits</span>'+chips(['Ember Raider','Monastery','Arena set','Casual'],(0,))+'<span class="mut" style="margin-left:auto">Cost</span> '+money(42,10)+' '+btn('Undo','g')+btn('Apply','p')+'</div>')
w=win(28,72,1136,520,'Transmogrification',b,icon='Icons__Modules__64__theme',sub='TransmogFrame (12.x) · outfits, situations, slots',tabs=['Outfits','Appearances','Situations','Custom sets'],active=1)
dr=win(28,610,420,230,'Dressing room',model(10,8,180,180,'DressUpFrame')+at(200,12,'<div style="width:200px">'+btn('Reset')+' '+btn('Undress')+'<div class="mut" style="margin-top:10px;font-size:10.5px">Shares the same look as the Transmog skin; link and outfit buttons are Phoenix buttons.</div></div>'),icon='Icons__Modules__64__theme',sub='tab preview',z=11)
s=side('partial','Skins pack <b>transmog</b> and <b>dressingRoom</b>: shells only. Slot list, appearance grid, outfit bar, situations editor keep Blizzard art.',
 ['Slot rail with pending-change highlight in accent','Appearance cards in Phoenix frames, selected glow','Outfit chips + cost + Apply as primary','Dressing room uses the same card style'],
 ['Apply (C_Transmog) is only ever Blizzard\'s own button; Phoenix restyles, never calls','12.x TransmogFrame is new code: frame keys are read at runtime; a missing key is skipped, never errors','Models: backdrop only'],
 ['Skin on/off','Card size','Pending highlight','Cost line','Outfit chips'])
page('06_transmog','Transmog & dressing room','Skins · Ember theme · TransmogFrame, DressUpFrame',w+dr+s)
